insert into public.library_exercises (key, version, sport, name, category, muscles, pattern, equipment, level, instructions, record_fields, alternatives, video_url, image_url) values
  ('agachamento-barra', 1, 'fitness', 'Agachamento com barra', 'forca', array['quadríceps','glúteos','core']::text[], 'agachar', array['barra','suporte']::text[], 'intermedio', 'Barra nas costas, pés à largura dos ombros. Desce com o peito alto até as coxas ficarem paralelas e sobe a empurrar o chão.', array['carga','repeticoes','esforco']::text[], array['agachamento-goblet','leg-press']::text[], null, null),
  ('agachamento-goblet', 1, 'fitness', 'Agachamento goblet', 'forca', array['quadríceps','glúteos']::text[], 'agachar', array['haltere','kettlebell']::text[], 'iniciante', 'Peso junto ao peito, cotovelos por dentro dos joelhos. Desce devagar e mantém os calcanhares no chão.', array['carga','repeticoes']::text[], array['agachamento-barra','agachamento-peso-corporal']::text[], null, null),
  ('agachamento-peso-corporal', 1, 'fitness', 'Agachamento com o peso do corpo', 'forca', array['quadríceps','glúteos']::text[], 'agachar', array[]::text[], 'iniciante', 'Braços à frente para equilíbrio. Desce até onde mantiveres as costas direitas.', array['repeticoes']::text[], array['agachamento-goblet']::text[], null, null),
  ('leg-press', 1, 'fitness', 'Prensa de pernas', 'forca', array['quadríceps','glúteos']::text[], 'agachar', array['máquina']::text[], 'iniciante', 'Pés a meio da plataforma. Desce até os joelhos fazerem 90 graus sem tirar a lombar do encosto.', array['carga','repeticoes']::text[], array['agachamento-goblet']::text[], null, null),
  ('peso-morto', 1, 'fitness', 'Peso morto', 'forca', array['posteriores da coxa','glúteos','lombar']::text[], 'dobrar a anca', array['barra']::text[], 'intermedio', 'Barra junto às canelas, costas neutras. Empurra o chão e estende a anca até ficares direito.', array['carga','repeticoes','esforco']::text[], array['peso-morto-romeno','hip-thrust']::text[], null, null),
  ('peso-morto-romeno', 1, 'fitness', 'Peso morto romeno', 'forca', array['posteriores da coxa','glúteos']::text[], 'dobrar a anca', array['barra','halteres']::text[], 'intermedio', 'Joelhos ligeiramente fletidos. Leva a anca atrás com o peso perto das pernas até sentires os posteriores.', array['carga','repeticoes']::text[], array['peso-morto','ponte-gluteos']::text[], null, null),
  ('hip-thrust', 1, 'fitness', 'Hip thrust', 'forca', array['glúteos']::text[], 'dobrar a anca', array['barra','banco']::text[], 'intermedio', 'Omoplatas no banco, barra na anca. Sobe até a anca ficar alinhada com o tronco e aperta os glúteos.', array['carga','repeticoes']::text[], array['ponte-gluteos']::text[], null, null),
  ('ponte-gluteos', 1, 'fitness', 'Ponte de glúteos', 'forca', array['glúteos']::text[], 'dobrar a anca', array[]::text[], 'iniciante', 'Deitado, pés no chão. Sobe a anca sem arquear a lombar e desce devagar.', array['repeticoes']::text[], array['hip-thrust']::text[], null, null),
  ('afundo', 1, 'fitness', 'Afundo', 'forca', array['quadríceps','glúteos']::text[], 'unilateral', array['halteres']::text[], 'iniciante', 'Passo grande à frente, desce até o joelho de trás quase tocar no chão. Tronco direito.', array['carga','repeticoes']::text[], array['agachamento-bulgaro','step-up']::text[], null, null),
  ('agachamento-bulgaro', 1, 'fitness', 'Agachamento búlgaro', 'forca', array['quadríceps','glúteos']::text[], 'unilateral', array['banco','halteres']::text[], 'intermedio', 'Pé de trás no banco. Desce na vertical com o peso na perna da frente.', array['carga','repeticoes']::text[], array['afundo']::text[], null, null),
  ('step-up', 1, 'fitness', 'Subida ao banco', 'forca', array['quadríceps','glúteos']::text[], 'unilateral', array['banco']::text[], 'iniciante', 'Pé inteiro no banco. Sobe a empurrar com essa perna, sem impulso da de baixo.', array['carga','repeticoes']::text[], array['afundo']::text[], null, null),
